package rw.schoolpass.model;
import jakarta.persistence.*; @Entity @Table(name="school_profile") public class SchoolProfile { @Id private Long id=1L; private String schoolName=""; private String principalName=""; private String academicYear=""; private String contactPhone=""; private String contactEmail=""; private String address=""; public Long getId(){return id;} public void setId(Long v){id=v;} public String getSchoolName(){return schoolName;} public void setSchoolName(String v){schoolName=v;} public String getPrincipalName(){return principalName;} public void setPrincipalName(String v){principalName=v;} public String getAcademicYear(){return academicYear;} public void setAcademicYear(String v){academicYear=v;} public String getContactPhone(){return contactPhone;} public void setContactPhone(String v){contactPhone=v;} public String getContactEmail(){return contactEmail;} public void setContactEmail(String v){contactEmail=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} }
